 "content": "def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    # The frame bounds the drawing region. Markers are the interior 3-cells.
    points = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 3]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    markers = [(r, c) for r, c in points if r0 < r < r1 and c0 < c < c1]

    # Fill the frame's interior with 4, then extend the 2-patterns from markers
    # by the evidence-supported demo rule (not fully established for all cases).
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            out[r][c] = 4
    for mr, mc in markers:
        for rad in (1, 2):
            for r in range(max(r0 + 1, mr - rad), min(r1, mr + rad + 1)):
                for c in range(max(c0 + 1, mc - rad), min(c1, mc + rad + 1)):
                    if max(abs(r - mr), abs(c - mc)) == rad:
                        out[r][c] = 2
        out[mr][mc] = 3
    return out

if __name__ == '__main__':
    pass
